import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathArrays_linearCombination_TriageGen0Test {

    private static final double EPSILON = 1e-12;

    @Test
    public void testLinearCombination_StandardCase() throws DimensionMismatchException {
        double[] a = {1.0, 2.0, 3.0};
        double[] b = {4.0, 5.0, 6.0};
        // Expected: 1*4 + 2*5 + 3*6 = 4 + 10 + 18 = 32
        double expected = 32.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testLinearCombination_DimensionMismatch() {
        double[] a = {1.0, 2.0};
        double[] b = {1.0, 2.0, 3.0};
        try {
            MathArrays.linearCombination(a, b);
            org.junit.Assert.fail("Expected DimensionMismatchException");
        } catch (DimensionMismatchException e) {
            // Success
        }
    }

    @Test
    public void testLinearCombination_SingleElement() throws DimensionMismatchException {
        // The loop for sLowSum uses len-1, if len=1, it might behave differently.
        // However, the code logic for sLowSum requires len >= 2 to enter the second loop.
        // Let's test with len=2 to ensure the logic for sLowSum and sHighPrev is covered.
        double[] a = {2.0, 3.0};
        double[] b = {4.0, 5.0};
        // Expected: 2*4 + 3*5 = 8 + 15 = 23
        double expected = 23.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testLinearCombination_ThreeElements() throws DimensionMismatchException {
        // Tests the loop: for (int i = 1; i < lenMinusOne; i++)
        double[] a = {1.0, 2.0, 3.0};
        double[] b = {1.0, 1.0, 1.0};
        // Expected: 1*1 + 2*1 + 3*1 = 6
        double expected = 6.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testLinearCombination_NaNFallback() throws DimensionMismatchException {
        // Trigger the Double.isNaN(result) block
        // Using Infinity to cause NaN during the complex summation logic
        double[] a = {Double.POSITIVE_INFINITY, 1.0};
        double[] b = {1.0, 1.0};

        // The result of the complex arithmetic will likely be NaN
        // The fallback logic: result = sum(a[i] * b[i])
        // Infinity * 1 + 1 * 1 = Infinity
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(Double.POSITIVE_INFINITY, actual, 0.0);
    }

    @Test
    public void testLinearCombination_NaNInput() throws DimensionMismatchException {
        // If input contains NaN, result becomes NaN, triggers fallback
        double[] a = {Double.NaN, 1.0};
        double[] b = {1.0, 1.0};
        // Fallback: NaN * 1 + 1 * 1 = NaN
        double actual = MathArrays.linearCombination(a, b);
        org.junit.Assert.assertTrue(Double.isNaN(actual));
    }

    @Test
    public void testLinearCombination_LargeValues() throws DimensionMismatchException {
        double[] a = {1e15, 2e15};
        double[] b = {1e15, 2e15};
        // Expected: 1e30 + 4e30 = 5e30
        double expected = 5e30;
        double actual = MathArrays.linearCombination(a, b);
        // Use a larger epsilon for very large numbers
        assertEquals(expected, actual, 1e20);
    }

    @Test
    public void testLinearCombination_Zeros() throws DimensionMismatchException {
        double[] a = {0.0, 0.0, 0.0};
        double[] b = {0.0, 0.0, 0.0};
        double expected = 0.0;
        double actual = MathArrays.linearCombination(a, b);
        assertEquals(expected, actual, EPSILON);
    }
}
